package in.malabartrails;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.boot.CommandLineRunner;import org.springframework.data.domain.Sort;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@RestController public class ApiController {
 private final PackageRepository packages;private final ItineraryDayRepository itineraries;private final SeasonalPriceRepository prices;private final PackageMediaRepository media;private final PackageVersionRepository versions;private final DestinationRepository destinations;private final EnquiryRepository enquiries;private final EnquiryNoteRepository notes;private final EnquiryActivityRepository activities;private final StaffRepository staff;private final AuthService auth;private final PasswordEncoder encoder;private final GeminiEnquirySummaryService summaries;private final ObjectMapper json;
 public ApiController(PackageRepository packages,ItineraryDayRepository itineraries,SeasonalPriceRepository prices,PackageMediaRepository media,PackageVersionRepository versions,DestinationRepository destinations,EnquiryRepository enquiries,EnquiryNoteRepository notes,EnquiryActivityRepository activities,StaffRepository staff,AuthService auth,PasswordEncoder encoder,GeminiEnquirySummaryService summaries,ObjectMapper json){this.packages=packages;this.itineraries=itineraries;this.prices=prices;this.media=media;this.versions=versions;this.destinations=destinations;this.enquiries=enquiries;this.notes=notes;this.activities=activities;this.staff=staff;this.auth=auth;this.encoder=encoder;this.summaries=summaries;this.json=json;}
 public record EnquiryRequest(@NotBlank @Size(max=120)String fullName,@NotBlank @Email @Size(max=254)String email,@NotBlank @Pattern(regexp="[+0-9() -]{7,20}")String phone,@NotBlank @Size(max=160)String destination,@NotNull LocalDate travelDate,@Min(1) @Max(30)int adults,@Min(0) @Max(20)int children,@DecimalMin("0")BigDecimal budget,@Size(max=3000)String message,boolean whatsappConsent,UUID packageId){}
 public record PackageRequest(@NotBlank @Size(max=180)String slug,@NotBlank @Size(max=200)String title,@NotBlank @Size(max=160)String destination,@Size(max=160)String region,@Size(max=800)String summary,String description,String coverImageUrl,@Min(1)int durationNights,@Size(max=120)String hotelCategory,@NotNull @DecimalMin("0")BigDecimal startingPrice,String inclusions,String exclusions,@Pattern(regexp="DRAFT|PUBLISHED|ARCHIVED")String status,OffsetDateTime publishAt,Double latitude,Double longitude,String mapEmbedUrl,String hotelDetails,String availabilityMessage){}
 public record ItineraryRequest(@Min(1)int dayNumber,@NotBlank @Size(max=200)String title,@NotBlank String description){} public record PriceRequest(@NotBlank @Size(max=100)String label,@NotNull LocalDate startsOn,@NotNull LocalDate endsOn,@NotNull @DecimalMin("0")BigDecimal price){} public record MediaRequest(@NotBlank String imageUrl,@Size(max=240)String altText,@Min(0)int sortOrder){} public record NoteRequest(@NotBlank @Size(max=5000)String body){} public record AssignmentRequest(UUID staffId){} public record LoginRequest(@Email String email,@NotBlank String password){}
 @GetMapping("/packages") public List<Map<String,Object>> publicPackages(@RequestParam(required=false)String q,@RequestParam(required=false)String region){return packages.findByStatusOrderByTitleAsc("PUBLISHED").stream().filter(this::isLive).filter(p->q==null||q.isBlank()||(p.title+" "+p.destination+" "+Objects.toString(p.region,"")).toLowerCase().contains(q.toLowerCase())).filter(p->region==null||region.isBlank()||Objects.toString(p.region,"").equalsIgnoreCase(region)).map(this::packageSummary).toList();}
 @GetMapping("/packages/{slug}") public Map<String,Object> publicPackage(@PathVariable String slug){var p=packages.findBySlugAndStatus(slug,"PUBLISHED").filter(this::isLive).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));return packageDetail(p);}
 @GetMapping("/destinations") public List<Destination> publicDestinations(){return destinations.findByStatusOrderByNameAsc("PUBLISHED");}
 @GetMapping("/destinations/{slug}") public Map<String,Object> publicDestination(@PathVariable String slug){Destination d=destinations.findBySlugAndStatus(slug,"PUBLISHED").orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));var related=packages.findByStatusOrderByTitleAsc("PUBLISHED").stream().filter(this::isLive).filter(p->(p.destination+" "+Objects.toString(p.region,"")).toLowerCase().contains(d.name.toLowerCase())).map(this::packageSummary).toList();return Map.of("destination",d,"packages",related);}
 @PostMapping("/enquiries") public ResponseEntity<?> createEnquiry(@Valid @RequestBody EnquiryRequest b,@RequestHeader(value="Idempotency-Key",required=false)String key){if(key!=null){var old=enquiries.findByIdempotencyKey(key);if(old.isPresent())return ResponseEntity.ok(Map.of("id",old.get().id,"acknowledgement","recorded"));}Enquiry e=new Enquiry();e.fullName=b.fullName();e.email=b.email();e.phone=b.phone();e.destination=b.destination();e.travelDate=b.travelDate();e.adults=b.adults();e.children=b.children();e.budget=b.budget();e.message=b.message();e.whatsappConsent=b.whatsappConsent();e.packageId=b.packageId();e.idempotencyKey=key;var r=summaries.summarize(e.destination,e.travelDate,e.adults,e.children,e.budget,e.message);e.aiStatus=r.status();e.aiSummary=r.summary();e=enquiries.save(e);return ResponseEntity.status(201).body(Map.of("id",e.id,"acknowledgement","recorded","delivery","This is a system acknowledgement simulation; no message was sent."));}
 @PostMapping("/auth/login")public ResponseEntity<?> login(@Valid @RequestBody LoginRequest b,HttpServletResponse r){auth.login(b.email(),b.password(),r);return ResponseEntity.ok(Map.of("authenticated",true));} @PostMapping("/auth/logout")public ResponseEntity<?> logout(HttpServletResponse r){Cookie c=new Cookie("mt_session","");c.setHttpOnly(true);c.setPath("/");c.setMaxAge(0);c.setAttribute("SameSite","Lax");r.addCookie(c);return ResponseEntity.noContent().build();}
 @GetMapping("/admin/dashboard")public Map<String,Object> dashboard(){long total=enquiries.count(),fresh=enquiries.countByStatus("NEW");var breakdown=enquiries.countGroupedByStatus().stream().map(r->Map.of("name",r[0].toString(),"value",((Number)r[1]).longValue())).toList();return Map.of("totalEnquiries",total,"newEnquiries",fresh,"pendingEnquiries",enquiries.countByStatus("CONTACTED"),"publishedPackages",packages.countByStatus("PUBLISHED"),"recentEnquiries",enquiries.findTop10ByOrderByCreatedAtDesc(),"statusBreakdown",breakdown);}
 @GetMapping("/admin/packages")public List<Map<String,Object>> adminPackages(){return packages.findAll(Sort.by(Sort.Direction.DESC,"updatedAt")).stream().map(this::packageSummary).toList();} @GetMapping("/admin/packages/{id}")public Map<String,Object> adminPackage(@PathVariable UUID id){return packageDetail(requirePackage(id));}
 @PostMapping("/admin/packages")public ResponseEntity<Map<String,Object>> createPackage(@Valid @RequestBody PackageRequest b,Authentication a){PackageEntity p=new PackageEntity();copy(b,p);p.status=b.status()==null?"DRAFT":b.status();p.version=1;setPublishing(p);p=packages.save(p);snapshot(p,actor(a));return ResponseEntity.status(201).body(packageDetail(p));}
 @PutMapping("/admin/packages/{id}")public Map<String,Object> updatePackage(@PathVariable UUID id,@Valid @RequestBody PackageRequest b,Authentication a){PackageEntity p=requirePackage(id);copy(b,p);p.version++;setPublishing(p);p=packages.save(p);snapshot(p,actor(a));return packageDetail(p);}
 @PostMapping("/admin/packages/{id}/duplicate")public ResponseEntity<Map<String,Object>> duplicate(@PathVariable UUID id,Authentication a){PackageEntity s=requirePackage(id),p=new PackageEntity();copyFrom(s,p);p.slug=uniqueSlug(s.slug+"-copy");p.title=s.title+" (copy)";p.status="DRAFT";p.publishAt=null;p.publishedAt=null;p.version=1;p=packages.save(p);for(ItineraryDay d:itineraries.findByTravelPackageIdOrderByDayNumberAsc(id)){ItineraryDay n=new ItineraryDay();n.travelPackage=p;n.dayNumber=d.dayNumber;n.title=d.title;n.description=d.description;itineraries.save(n);}snapshot(p,actor(a));return ResponseEntity.status(201).body(packageDetail(p));}
 @GetMapping("/admin/packages/{id}/history")public List<PackageVersion> history(@PathVariable UUID id){requirePackage(id);return versions.findByPackageIdOrderByVersionDesc(id);} @PostMapping("/admin/packages/{id}/history/{version}/restore")public Map<String,Object> restore(@PathVariable UUID id,@PathVariable int version,Authentication a){PackageEntity p=requirePackage(id);PackageVersion v=versions.findByPackageIdAndVersion(id,version).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));try{copy(json.readValue(v.snapshot,PackageRequest.class),p);p.version++;p=packages.save(p);snapshot(p,actor(a));return packageDetail(p);}catch(JsonProcessingException x){throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Cannot restore this snapshot");}}
 @GetMapping("/admin/packages/{id}/itinerary")public List<ItineraryDay> itinerary(@PathVariable UUID id){requirePackage(id);return itineraries.findByTravelPackageIdOrderByDayNumberAsc(id);}@PutMapping("/admin/packages/{id}/itinerary")public List<ItineraryDay> saveItinerary(@PathVariable UUID id,@Valid @RequestBody List<ItineraryRequest> b,Authentication a){PackageEntity p=requirePackage(id);if(b.stream().map(ItineraryRequest::dayNumber).distinct().count()!=b.size())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Day numbers must be unique");itineraries.deleteAll(itineraries.findByTravelPackageIdOrderByDayNumberAsc(id));var out=new ArrayList<ItineraryDay>();for(var x:b){ItineraryDay d=new ItineraryDay();d.travelPackage=p;d.dayNumber=x.dayNumber();d.title=x.title();d.description=x.description();out.add(itineraries.save(d));}snapshot(p,actor(a));return out;}
 @GetMapping("/admin/packages/{id}/seasonal-prices")public List<SeasonalPrice> seasonalPrices(@PathVariable UUID id){requirePackage(id);return prices.findByTravelPackageIdOrderByStartsOnAsc(id);}@PutMapping("/admin/packages/{id}/seasonal-prices")public List<SeasonalPrice> savePrices(@PathVariable UUID id,@Valid @RequestBody List<PriceRequest> b,Authentication a){PackageEntity p=requirePackage(id);if(b.stream().anyMatch(x->x.endsOn().isBefore(x.startsOn())))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Season end must be after its start");prices.deleteAll(prices.findByTravelPackageIdOrderByStartsOnAsc(id));var out=new ArrayList<SeasonalPrice>();for(var x:b){SeasonalPrice s=new SeasonalPrice();s.travelPackage=p;s.label=x.label();s.startsOn=x.startsOn();s.endsOn=x.endsOn();s.price=x.price();out.add(prices.save(s));}snapshot(p,actor(a));return out;}
 @PutMapping("/admin/packages/{id}/media")public List<PackageMedia> saveMedia(@PathVariable UUID id,@Valid @RequestBody List<MediaRequest> b,Authentication a){requirePackage(id);media.deleteByPackageId(id);var out=new ArrayList<PackageMedia>();for(var x:b){PackageMedia m=new PackageMedia();m.packageId=id;m.imageUrl=x.imageUrl();m.altText=x.altText();m.sortOrder=x.sortOrder();out.add(media.save(m));}snapshot(requirePackage(id),actor(a));return out;}
 @GetMapping("/admin/enquiries")public List<Enquiry> adminEnquiries(){return enquiries.findAll(Sort.by(Sort.Direction.DESC,"createdAt"));}@GetMapping("/admin/enquiries/{id}")public Map<String,Object> enquiry(@PathVariable UUID id){Enquiry e=requireEnquiry(id);return Map.of("enquiry",e,"notes",notes.findByEnquiryIdOrderByCreatedAtDesc(id),"activity",activities.findByEnquiryIdOrderByCreatedAtDesc(id));}@PatchMapping("/admin/enquiries/{id}/status")public Enquiry updateStatus(@PathVariable UUID id,@RequestParam @Pattern(regexp="NEW|CONTACTED|QUALIFIED|QUOTED|CONVERTED|CLOSED")String status,Authentication a){Enquiry e=requireEnquiry(id);String old=e.status;e.status=status;e=enquiries.save(e);activity(id,actor(a),"STATUS_CHANGED",old+" → "+status);return e;}@PatchMapping("/admin/enquiries/{id}/assignment")public Enquiry assign(@PathVariable UUID id,@RequestBody AssignmentRequest b,Authentication a){Enquiry e=requireEnquiry(id);if(b.staffId()!=null&&staff.findById(b.staffId()).isEmpty())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Staff member not found");e.assignedStaffId=b.staffId();e=enquiries.save(e);activity(id,actor(a),"ASSIGNMENT_CHANGED",b.staffId()==null?"Unassigned":"Assigned");return e;}@PostMapping("/admin/enquiries/{id}/notes")public EnquiryNote addNote(@PathVariable UUID id,@Valid @RequestBody NoteRequest b,Authentication a){requireEnquiry(id);EnquiryNote n=new EnquiryNote();n.enquiryId=id;n.authorEmail=actor(a);n.body=b.body();n=notes.save(n);activity(id,n.authorEmail,"NOTE_ADDED",null);return n;}@PostMapping("/admin/enquiries/{id}/summary")public Enquiry regenerateSummary(@PathVariable UUID id){Enquiry e=requireEnquiry(id);var r=summaries.summarize(e);e.aiStatus=r.status();e.aiSummary=r.summary();return enquiries.save(e);}
 private boolean isLive(PackageEntity p){return p.publishAt==null||!p.publishAt.isAfter(OffsetDateTime.now());}private PackageEntity requirePackage(UUID id){return packages.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));}private Enquiry requireEnquiry(UUID id){return enquiries.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));}
 private Map<String,Object> packageSummary(PackageEntity p){var o=new LinkedHashMap<String,Object>();o.put("id",p.id);o.put("slug",p.slug);o.put("title",p.title);o.put("destination",p.destination);o.put("region",p.region);o.put("summary",p.summary);o.put("coverImageUrl",p.coverImageUrl);o.put("durationNights",p.durationNights);o.put("hotelCategory",p.hotelCategory);o.put("startingPrice",p.startingPrice);o.put("status",p.status);o.put("publishAt",p.publishAt);return o;}private Map<String,Object> packageDetail(PackageEntity p){var o=packageSummary(p);o.put("description",p.description);o.put("inclusions",p.inclusions);o.put("exclusions",p.exclusions);o.put("version",p.version);o.put("publishedAt",p.publishedAt);o.put("latitude",p.latitude);o.put("longitude",p.longitude);o.put("mapEmbedUrl",p.mapEmbedUrl);o.put("hotelDetails",p.hotelDetails);o.put("availabilityMessage",p.availabilityMessage);o.put("itinerary",itineraries.findByTravelPackageIdOrderByDayNumberAsc(p.id));o.put("seasonalPrices",prices.findByTravelPackageIdOrderByStartsOnAsc(p.id));o.put("media",media.findByPackageIdOrderBySortOrderAsc(p.id));return o;}
 private void copy(PackageRequest b,PackageEntity p){p.slug=b.slug().trim().toLowerCase(Locale.ROOT);p.title=b.title().trim();p.destination=b.destination().trim();p.region=b.region();p.summary=b.summary();p.description=b.description();p.coverImageUrl=b.coverImageUrl();p.durationNights=b.durationNights();p.hotelCategory=b.hotelCategory();p.startingPrice=b.startingPrice();p.inclusions=b.inclusions();p.exclusions=b.exclusions();p.status=b.status()==null?"DRAFT":b.status();p.publishAt=b.publishAt();p.latitude=b.latitude();p.longitude=b.longitude();p.mapEmbedUrl=b.mapEmbedUrl();p.hotelDetails=b.hotelDetails();p.availabilityMessage=b.availabilityMessage();}private void copyFrom(PackageEntity s,PackageEntity p){p.slug=s.slug;p.title=s.title;p.destination=s.destination;p.region=s.region;p.summary=s.summary;p.description=s.description;p.coverImageUrl=s.coverImageUrl;p.durationNights=s.durationNights;p.hotelCategory=s.hotelCategory;p.startingPrice=s.startingPrice;p.inclusions=s.inclusions;p.exclusions=s.exclusions;p.latitude=s.latitude;p.longitude=s.longitude;p.mapEmbedUrl=s.mapEmbedUrl;p.hotelDetails=s.hotelDetails;p.availabilityMessage=s.availabilityMessage;}private void setPublishing(PackageEntity p){if("PUBLISHED".equals(p.status)&&p.publishAt==null)p.publishedAt=OffsetDateTime.now();}private void snapshot(PackageEntity p,String actor){try{PackageVersion v=new PackageVersion();v.packageId=p.id;v.version=p.version;v.snapshot=json.writeValueAsString(new PackageRequest(p.slug,p.title,p.destination,p.region,p.summary,p.description,p.coverImageUrl,p.durationNights,p.hotelCategory,p.startingPrice,p.inclusions,p.exclusions,p.status,p.publishAt,p.latitude,p.longitude,p.mapEmbedUrl,p.hotelDetails,p.availabilityMessage));v.editorEmail=actor;versions.save(v);}catch(JsonProcessingException ignored){}}private String actor(Authentication a){return a==null?"system":a.getName();}private void activity(UUID id,String a,String action,String detail){EnquiryActivity x=new EnquiryActivity();x.enquiryId=id;x.actorEmail=a;x.action=action;x.detail=detail;activities.save(x);}private String uniqueSlug(String base){String x=base;int n=2;while(packages.findAll().stream().anyMatch(p->p.slug.equals(x)))x=base+"-"+n++;return x;}
 @Bean CommandLineRunner bootstrapAdmin(@Value("${app.admin-email:}")String email,@Value("${app.admin-password:}")String password){return args->{if(!email.isBlank()&&!password.isBlank()&&staff.findByEmailIgnoreCase(email).isEmpty()){StaffUser u=new StaffUser();u.email=email.toLowerCase(Locale.ROOT);u.passwordHash=encoder.encode(password);u.role="ADMIN";staff.save(u);}};}
}
